  const d = ctx({ E: 100, A: 0, B: 0, H: 0 });
  assert.equal(run(d, () => escrow.settle(d, "E", "A", "B", "H", 100, 100, 0)), "ok");
  assert.deepEqual(d.audit.events.map((e) => e.kind), ["Moved", "Captured"]);
  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 100, 0, 0), "BadPart");
  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 100, 101, 0), "BadPart");
  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 100, 50, 60), "BadFee");
  expectRun({ E: 150, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 200, 100, 0), "Insufficient 50",
